import { ChangeDetectionStrategy, Component, computed, input } from '@angular/core';

@Component({
  selector: 'aevko-progress',
  standalone: true,
  template: '<span class="indicator" [style.inline-size.%]="percentage()"></span>',
  styleUrl: './progress.component.css',
  changeDetection: ChangeDetectionStrategy.OnPush,
  host: {
    'data-slot': 'progress',
    role: 'progressbar',
    '[attr.aria-label]': 'label()',
    '[attr.aria-valuemin]': '0',
    '[attr.aria-valuemax]': 'max()',
    '[attr.aria-valuenow]': 'value() === null ? null : normalized()',
    '[attr.data-state]': 'value() === null ? "indeterminate" : "determinate"',
  },
})
export class AevkoProgress {
  readonly label = input.required<string>();
  readonly value = input<number | null>(null);
  readonly max = input(100);
  protected readonly normalized = computed(() =>
    Math.min(Math.max(this.value() ?? 0, 0), Math.max(this.max(), 1)),
  );
  protected readonly percentage = computed(
    () => (this.normalized() / Math.max(this.max(), 1)) * 100,
  );
}

:host {
  background: var(--aevko-surface, #f4f4f5);
  display: block;
  height: 0.5rem;
  overflow: hidden;
  position: relative;
  width: 100%;
}
.indicator {
  background: var(--aevko-foreground, #09090b);
  display: block;
  height: 100%;
  transition: inline-size 180ms ease;
}
:host([data-state='indeterminate']) .indicator {
  animation: aevko-progress 1.2s ease-in-out infinite;
  inline-size: 40%;
  position: absolute;
}
@keyframes aevko-progress {
  from {
    transform: translateX(-100%);
  }
  to {
    transform: translateX(250%);
  }
}
@media (prefers-reduced-motion: reduce) {
  .indicator {
    transition: none;
  }
  :host([data-state='indeterminate']) .indicator {
    animation-duration: 3s;
  }
}
